head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    // 사전 조건은 dataList 정적 데이터로 세팅됨 (추가 처리 없음)
};



// ignoreSpan 값별 CSV 다운로드 (파일명을 달리해 구분)
scwin.saveByIgnoreSpan = function (strValue, strFileName) {
    var options = { fileName : strFileName, delim : "," };

    if (strValue !== "") {
        options.ignoreSpan = strValue;
    }

    grd_span.saveCSV(options);
    scwin.setReturnValue("실행 : ignoreSpan=" + (strValue === "" ? "생략" : "'" + strValue + "'") + " → 다운로드 파일 " + strFileName);
};

// ① ignoreSpan 생략 (기본값 "0")
scwin.btn_save_default_onclick = function () {
    scwin.saveByIgnoreSpan("", "saveCSV_span_default.csv");
};

// ② ignoreSpan = "0"
scwin.btn_save_span0_onclick = function () {
    scwin.saveByIgnoreSpan("0", "saveCSV_span0.csv");
};

// ③ ignoreSpan = "1"
scwin.btn_save_span1_onclick = function () {
    scwin.saveByIgnoreSpan("1", "saveCSV_span1.csv");
};
